<?php declare(strict_types=1);
$shareText=$bankEvidenceText;$shareReason=$draft($duplicateCorrection?'correction_reason':'reason');$shareHash=$draft('group_hash');$shareReuse=$draft('group_reuse');$shareDuplicate=$duplicateCorrection?($detail['transaction']['id']??''):'';$sharePending=(!$duplicateCorrection&&(!$canDecide||$row['state']!=='review'))||($duplicateCorrection&&$shareDuplicate==='');$shareReview=$bankGroupPrepared??null;$shareError='';$shareSelected=[];$shareTotal=0;$shareValid=true;
